  A.el('rect', { x: BX0, y: YT - 19, width: BX1 - BX0, height: 38, rx: 10, fill: '#1c1c1c', stroke: '#8a8a8a', 'stroke-width': 2, 'stroke-dasharray': '7 5' }, el);
