  var XD = X0 + NP * DX, XE = X0 + (NP + NG) * DX;               // "now" (prefix | plan), right end of the window
  var TY = 286, DY = 319;                                        // the two clock rows
  function X(f) { return X0 + (f + NP + 0.5) * DX; }             // centre of frame f (f = 0 is the first planned frame)
