  A.el('path', { d: 'M' + XD + ' 20V' + (DY + 14), stroke: '#6a6a6a', 'stroke-width': 2, 'stroke-dasharray': '3 6' }, el);
  txt(el, 24, 34, 'schematic', { fill: GREY });
