  var rowT1 = txt(el, 24, TY + 7, 'tracker: every frame', { fill: G, weight: 700 });
  var rowD0 = txt(el, 24, DY + 7, 'DiP: 10 denoising steps', { fill: BLUE, weight: 700 });
  var rowD1 = txt(el, 24, DY + 7, 'DiP: every 40 frames', { fill: BLUE, weight: 700 });

