    if (up) { o.torso = A.el('path', { 'stroke-width': 8.5 }, g); o.head = A.el('circle', { r: HR, stroke: 'none' }, g); }
    if (lo) { o.pel = A.el('circle', { r: 6.5, stroke: 'none' }, g); o.legN = A.el('path', { 'stroke-width': 6.5 }, g); }
