  function label(x, y, s, o) { return A.text(el, x, y, s, { size: o.size || 20, weight: o.weight || 500, fill: o.fill || C.mid, anchor: o.anchor || 'start', halo: false }); }
  A.el('line', { x1: 324, y1: 14, x2: 324, y2: 271, stroke: '#2c2c2c', 'stroke-width': 2 }, el);
