      var An = [x0, yG - 5];
      var Kn = [An[0] + L.shin * Math.sin(a1), An[1] - L.shin * Math.cos(a1)];
      var H = [Kn[0] + L.thigh * Math.sin(a2), Kn[1] - L.thigh * Math.cos(a2)];
