      var S = [H[0] + 0.86 * L.torso * s3, H[1] - 0.86 * L.torso * c3];
      var E = [S[0] + L.upper * Math.sin(b1), S[1] + L.upper * Math.cos(b1)];
      var W = [E[0] + L.fore * Math.sin(b2), E[1] + L.fore * Math.cos(b2)];
