  var NREC = 40, pile = [], rec = [];
  for (i = 0; i < N0; i++) pile.push(A.el('circle', { r: 4.4, fill: C.amber, opacity: 0 }, el));
  for (i = 0; i < NREC; i++) rec.push(A.el('circle', { r: 4.4, fill: C.amber, opacity: 0 }, el));
