  var leg1 = K.text(el, W, 18, '<tspan style="fill:' + C.g + '">■</tspan>  what the return counts: ' + K.ss('γ', 't', false, '') + K.ss(' r', 't', true, '') +
                    '        <tspan style="fill:#fff;font-weight:700">—</tspan>  weight ' + K.ss('γ', 't', false, ''), 20, C.mid, 500, 'end');
