  for (i = 0; i < SB.LINKS.length; i++) dots.push(A.el('circle', { 'stroke-width': 2.2 }, el));
  var root = A.el('circle', { r: 7.5, fill: AM, stroke: '#0c0c0c', 'stroke-width': 2 }, el);
