  SB.txt(A, el, CX + DX, GY + 34, 'target', { size: 20, fill: G, anchor: 'middle', weight: 700 });
  // the eight control modes
  SB.txt(A, el, 290, 78, 'control mode', { size: 20, fill: C.mute });
  SB.txt(A, el, 546, 78, 'links', { size: 20, fill: C.mute, anchor: 'end' });
