    A.set(p.ask, { cx: A.lerp(ln.x2, ln.x1, v).toFixed(1), cy: A.lerp(ln.y2, ln.y1, v).toFixed(1) });
    A.set(ln.dot, { cx: A.lerp(ln.x1, ln.x2, v).toFixed(1), cy: A.lerp(ln.y1, ln.y2, v).toFixed(1) });
